// overviews/sharkninja-tam-data.js — FROZEN data for SharkNinja Deep Dive ▸ TAM (category expansion).
//
// What it is: every statement SharkNinja management (and, marked, the analysts questioning them)
// made about the addressable market, the sub-category count, the categories entered, the growth
// algorithm, international runway and market share — from the Jul 2023 spin-off to the Goldman
// Sachs Global Consumer and Retail Conference of Sep 15 2026.
//
// Frozen: retrieved through Quartr (13 earnings calls, 13 conference transcripts, 15 decks, read in
// full) and SEC filings on Sep 15 2026. Nothing here is fetched at runtime. Every item carries its
// Quartr deep link; the tq/sq helpers below only rebuild those exact URLs.
//
// Provenance / contradiction caveats worth keeping:
//  • No investor deck ever sizes TAM in dollars. "Large and Expanding TAM" is a headline bullet from
//    the Mar 28 2024 deck on, never quantified. Every dollar TAM here was SPOKEN.
//  • $125–130B: management said it on the Q2 2026 call (Aug 5 2026) as the TAM "coming out of the
//    year". On Sep 15 2026 the Goldman analyst (Brooke Roach) stated it in her question; Barrocas did
//    not repeat or confirm it, so that point carries analyst:true.
//  • Analyst Randal Konik (Q2 2026 call) recalled a TAM of "well over about $100, I think, $12
//    billion" and a SAM of "about $40 billion" from ~3 years earlier. As transcribed; not converted,
//    not confirmed by any 2023 management source read.
//  • Counts: "categories", "product categories" and "subcategories" are used interchangeably. Decks
//    are year-end snapshots (27 → 31 → 36 → 38) and lag the spoken count. Same-session conflicts
//    (38 and 36 at Morgan Stanley Dec 2025) are kept both ways.
//  • Germany + France: "$2 billion markets individually" (Jun 2024) vs "combined … $2 billion"
//    (Sep 2024) vs "$2 billion of growth opportunity" (Dec 2024) vs "over $2 billion" (Sep 2025).
//  • Microwaves: "multi-billion" and "Over a $3 billion TAM" (Aug 5 2026) → "$4 billion TAM" (Sep 15).
//  • Q2 2026 call Q&A names "Ninja BlendBoss" as a 2026 new subcategory; the Q1 2026 prepared remarks
//    name Shark BlastBoss as #39 (BlendBoss is a blender inside an existing category). BlastBoss used.

var QB = 'https://web.quartr.com/companies/15145?companyId=15145&documentId=';
function tq(doc, ev, t) { return QB + doc + '&documentType=transcript&eventId=' + ev + '&navigation=external&utm_medium=referral&utm_source=mcp&targetTime=' + t; }
function sq(doc, ev, p) { return QB + doc + '&documentType=slide&eventId=' + ev + '&sp=' + p; }
function sqm(doc, ev, p) { return QB + doc + '&documentType=slide&eventId=' + ev + '&navigation=external&utm_medium=referral&utm_source=mcp&sp=' + p; }
// Log item builder: returns exactly the common log-item shape { d, type, src, who, topic, claim, q, url, analyst }.
function L(d, type, src, who, topic, claim, q, url, analyst) {
  return { d: d, type: type, src: src, who: who, topic: topic, claim: claim, q: q, url: url, analyst: !!analyst };
}
var MB = 'Mark Barrocas (CEO)', AQ = 'Adam Quigley (CFO)', PR = 'Patraic Reagan (CFO)', LF = 'Larry Flynn (interim CFO)', JL = 'James Lamb (IR)', DK = 'SharkNinja (deck)';

